signal(SIGCHLD, SIG_IGN);           /* children are reaped automatically */
for (;;) {
    int c = accept(s, NULL, NULL);
    if (c < 0) continue;
    if (fork() == 0) {              /* child */
        close(s);                   /* the child never accepts */
        serve(c);                   /* recv/send loop for this client */
        close(c);
        _exit(0);
    }
    close(c);                       /* parent keeps only the listening socket */
}

